/* The great stories of the Bible: a quick reference. Each entry: what happens (x), what it has been taken to teach (m),
   the virtues it commends (vt) and the failings it warns against (w), with a key verse (v) and, where the story is morally
   difficult, how readers have wrestled with it (hard). Eras group the stories in biblical order. */
window.STORY_ERAS = [
  ['beginnings', 'Beginnings', 'Genesis 1–11'],
  ['patriarchs', 'The patriarchs', 'Genesis 12–50'],
  ['exodus', 'Exodus and wilderness', 'Exodus – Deuteronomy'],
  ['land', 'The land and the judges', 'Joshua – Ruth'],
  ['kingdom', 'The kingdom', 'Samuel – Kings, Chronicles'],
  ['prophets', 'Prophets, exile and return', 'Prophets, Job, Esther, Daniel, Ezra–Nehemiah'],
  ['deutero', 'Deuterocanon', 'Tobit, Judith, Maccabees, Susanna'],
  ['jesus', 'The life of Jesus', 'The Gospels'],
  ['parables', 'The parables', 'The Gospels'],
  ['church', 'The early church', 'Acts – Revelation']
];

window.STORIES = [
  /* ── Beginnings ── */
  { id: 'creation', era: 'beginnings', t: 'Creation', p: 'Genesis 1:1–2:3', v: 'Gen.1.31',
    x: 'God speaks the world into being in six days, from light to living creatures, makes man and woman in his image, calls everything “very good,” and rests on the seventh day.',
    m: 'The world is ordered, good and not divine; every human being bears God’s image; work is followed by rest.', vt: ['gratitude', 'stewardship', 'rest'] },
  { id: 'eden', era: 'beginnings', t: 'The garden of Eden', p: 'Genesis 2:4–25', v: 'Gen.2.15',
    x: 'God forms the man from dust and breath, places him in a garden “to dress it and to keep it,” and makes the woman from his side so that neither is alone.',
    m: 'Human beings are made for work, for companionship and for trust in God; marriage is a partnership of equals made “one flesh.”', vt: ['stewardship', 'love', 'faithfulness'] },
  { id: 'fall', era: 'beginnings', t: 'The fall', p: 'Genesis 3', v: 'Gen.3.6',
    x: 'The serpent questions God’s word; the woman and the man eat the forbidden fruit, hide in shame, blame each other and are sent out of the garden, with a promise that the woman’s offspring will crush the serpent.',
    m: 'Temptation begins by doubting God’s goodness; sin breaks trust with God, with each other and with creation; blame-shifting is the first reflex of guilt.', vt: ['obedience', 'honesty', 'humility'], w: ['pride', 'deceit', 'blame'],
    hard: 'Christians since Augustine read this as the origin of original sin; Jewish tradition reads it as the birth of the evil inclination and human moral responsibility, without inherited guilt.' },
  { id: 'cain', era: 'beginnings', t: 'Cain and Abel', p: 'Genesis 4:1–16', v: 'Gen.4.7',
    x: 'Cain resents that God favours Abel’s offering, is warned that sin is “crouching at the door,” and kills his brother. Asked where Abel is, he answers, “Am I my brother’s keeper?”',
    m: 'Envy left unmastered becomes violence; we are responsible for one another; even the murderer is marked for protection, not vengeance.', vt: ['self-control', 'responsibility', 'mercy'], w: ['envy', 'anger'] },
  { id: 'enoch', era: 'beginnings', t: 'Enoch walks with God', p: 'Genesis 5:21–24', v: 'Gen.5.24',
    x: 'In a list of long lives ending in “and he died,” Enoch alone “walked with God: and he was not; for God took him.”',
    m: 'A life lived close to God stands out in a world of routine and death.', vt: ['faithfulness', 'devotion'] },
  { id: 'flood', era: 'beginnings', t: 'Noah and the flood', p: 'Genesis 6–9', v: 'Gen.9.13',
    x: 'The earth is filled with violence; God tells Noah, “a just man,” to build an ark for his family and the animals. After the flood God sets the rainbow as a sign of his covenant never again to destroy the earth by water.',
    m: 'God takes violence seriously; obedience can look foolish before it is vindicated; judgement is followed by a covenant of mercy with every living creature.', vt: ['obedience', 'faith', 'perseverance'], w: ['violence'],
    hard: 'The destruction of almost all life troubles many readers. Some read the story as a theological account of a regional catastrophe; others as history. The parallel Mesopotamian flood stories are discussed in the Ancient traditions unit.' },
  { id: 'noahsons', era: 'beginnings', t: 'Noah’s drunkenness', p: 'Genesis 9:18–29', v: 'Gen.9.23',
    x: 'Noah plants a vineyard and lies drunk and exposed; Ham sees and tells his brothers, while Shem and Japheth walk in backwards to cover their father.',
    m: 'Even the righteous fall; covering another’s shame is honourable, exposing it is not.', vt: ['respect', 'discretion'], w: ['drunkenness', 'mockery'],
    hard: 'The curse falls on Canaan, not Ham. Its misuse as the “curse of Ham” to justify African slavery has no basis in the text.' },
  { id: 'babel', era: 'beginnings', t: 'The tower of Babel', p: 'Genesis 11:1–9', v: 'Gen.11.4',
    x: 'People build a city and a tower “whose top may reach unto heaven” to make a name for themselves; God confuses their language and scatters them.',
    m: 'Human pride that seeks to reach heaven by its own power ends in confusion; at Pentecost (Acts 2) the scattered languages are reversed by gift.', vt: ['humility'], w: ['pride'] },

  /* ── Patriarchs ── */
  { id: 'callabram', era: 'patriarchs', t: 'The call of Abraham', p: 'Genesis 12:1–9', v: 'Gen.12.1',
    x: 'God tells Abram to leave his country and family for a land he will be shown, promising to make him a great nation through whom “all families of the earth” will be blessed. He goes.',
    m: 'Faith is setting out on a promise before seeing its fulfilment; God’s blessing is meant to reach all peoples.', vt: ['faith', 'obedience', 'courage'] },
  { id: 'lotchoice', era: 'patriarchs', t: 'Abraham and Lot part', p: 'Genesis 13', v: 'Gen.13.8',
    x: 'When their herdsmen quarrel, Abraham lets his nephew choose land first. Lot chooses the well-watered plain near Sodom.',
    m: 'Generosity and peace are worth more than advantage; choices made by sight alone can lead toward ruin.', vt: ['generosity', 'peacemaking'], w: ['greed'] },
  { id: 'covenant', era: 'patriarchs', t: 'The covenant under the stars', p: 'Genesis 15', v: 'Gen.15.6',
    x: 'Childless and old, Abram is told to count the stars: so shall his descendants be. “He believed in the LORD; and he counted it to him for righteousness.” God passes alone between the halves of the sacrifice.',
    m: 'Righteousness comes by trusting God’s promise; Paul makes this verse the centre of his argument (Romans 4).', vt: ['faith', 'trust'] },
  { id: 'hagar', era: 'patriarchs', t: 'Hagar and Ishmael', p: 'Genesis 16; 21:8–21', v: 'Gen.16.13',
    x: 'Sarai gives her Egyptian slave Hagar to Abram; mistreated, Hagar flees and is met by God, whom she names “the God who sees me.” Later she and Ishmael are sent away and God saves them in the desert.',
    m: 'God sees the outcast and the slave; impatient schemes to force God’s promise create lasting pain.', vt: ['compassion', 'patience'], w: ['impatience', 'cruelty'],
    hard: 'The story raises questions about slavery and the treatment of women. Islam honours Hagar (Hajar) and Ishmael as ancestors of the Arabs; her search for water is remembered in the Hajj.' },
  { id: 'mamre', era: 'patriarchs', t: 'Three visitors at Mamre', p: 'Genesis 18:1–15', v: 'Gen.18.14',
    x: 'Abraham runs to welcome three strangers and serves them a meal; they promise that Sarah will have a son, and Sarah laughs.',
    m: 'Hospitality to strangers may entertain angels unawares (Hebrews 13:2); “Is any thing too hard for the LORD?”', vt: ['hospitality', 'generosity', 'faith'] },
  { id: 'intercede', era: 'patriarchs', t: 'Abraham pleads for Sodom', p: 'Genesis 18:16–33', v: 'Gen.18.25',
    x: 'Abraham bargains with God from fifty righteous people down to ten: “Shall not the Judge of all the earth do right?”',
    m: 'The righteous intercede even for the wicked; God welcomes honest argument about justice.', vt: ['intercession', 'justice', 'boldness'] },
  { id: 'sodom', era: 'patriarchs', t: 'Sodom and Gomorrah', p: 'Genesis 19', v: 'Gen.19.29',
    x: 'Two angels lodge with Lot; the men of Sodom surround the house demanding to abuse them. The angels lead Lot’s family out, fire and brimstone fall on the cities, and Lot’s wife, looking back, becomes a pillar of salt.',
    m: 'Violence against the vulnerable stranger brings judgement; Ezekiel names Sodom’s sins as pride, excess and neglect of the poor (Ezekiel 16:49); clinging to what God is judging is deadly.', vt: ['hospitality', 'justice'], w: ['violence', 'pride', 'looking back'],
    hard: 'Lot’s offer of his daughters to the mob is condemned by most commentators. Readers differ on whether the story addresses homosexuality as such or gang rape and inhospitality; Jewish tradition stressed Sodom’s cruelty to the poor and stranger.' },
  { id: 'isaac', era: 'patriarchs', t: 'The binding of Isaac', p: 'Genesis 22:1–19', v: 'Gen.22.8',
    x: 'God tests Abraham by telling him to offer Isaac. On the mountain, as Abraham raises the knife, the angel stops him, and a ram caught in a thicket is offered instead.',
    m: 'Faith trusts God even when his command seems to contradict his promise; God provides; the story ends child sacrifice as a form of devotion.', vt: ['faith', 'obedience', 'trust'],
    hard: 'Jews call it the Akedah and read it on Rosh Hashanah. Kierkegaard’s Fear and Trembling wrestles with its terror; Christians see a foreshadowing of the Father giving the Son. Islam tells it of Ishmael (Qur’an 37:102–107).' },
  { id: 'rebekah', era: 'patriarchs', t: 'A wife for Isaac', p: 'Genesis 24', v: 'Gen.24.27',
    x: 'Abraham’s servant prays for a sign at the well; Rebekah offers water to him and all his camels, and agrees to go and marry Isaac.',
    m: 'God guides those who pray and act; generous kindness reveals character.', vt: ['prayer', 'kindness', 'faithfulness'] },
  { id: 'birthright', era: 'patriarchs', t: 'Esau sells his birthright', p: 'Genesis 25:27–34', v: 'Gen.25.34',
    x: 'Coming in hungry, Esau trades his birthright to his brother Jacob for a bowl of stew: “thus Esau despised his birthright.”',
    m: 'Trading a lasting good for an immediate appetite is folly (Hebrews 12:16).', vt: ['self-control', 'patience'], w: ['impulsiveness'] },
  { id: 'blessing', era: 'patriarchs', t: 'Jacob steals the blessing', p: 'Genesis 27', v: 'Gen.27.35',
    x: 'Rebekah and Jacob disguise Jacob as Esau to deceive the blind Isaac into giving him the firstborn’s blessing. Esau vows to kill him and Jacob flees.',
    m: 'Deceit wins a prize but breaks a family; the deceiver will himself be deceived (by Laban).', vt: ['honesty'], w: ['deceit', 'favouritism'] },
  { id: 'ladder', era: 'patriarchs', t: 'Jacob’s ladder', p: 'Genesis 28:10–22', v: 'Gen.28.15',
    x: 'Fleeing, Jacob sleeps on a stone and dreams of a stairway with angels; God promises to be with him. He names the place Bethel, “house of God.”',
    m: 'God meets people at their lowest and least deserving; grace comes before reform.', vt: ['hope', 'awe'] },
  { id: 'wrestle', era: 'patriarchs', t: 'Jacob wrestles with God', p: 'Genesis 32:22–32', v: 'Gen.32.28',
    x: 'Before meeting Esau, Jacob wrestles all night with a mysterious man, refuses to let go without a blessing, is wounded in the hip and renamed Israel, “he struggles with God.”',
    m: 'Honest struggle with God is a form of faith; blessing can come with a lasting wound.', vt: ['perseverance', 'honesty', 'faith'] },
  { id: 'reunion', era: 'patriarchs', t: 'Jacob and Esau reconciled', p: 'Genesis 33', v: 'Gen.33.4',
    x: 'Jacob sends gifts and bows seven times; Esau runs to meet him, embraces him and weeps.',
    m: 'Reconciliation requires humility from the guilty and generosity from the wronged.', vt: ['reconciliation', 'humility', 'forgiveness'] },
  { id: 'dinah', era: 'patriarchs', t: 'Dinah and the revenge at Shechem', p: 'Genesis 34', v: 'Gen.34.25',
    x: 'Dinah is violated by the prince of Shechem; her brothers Simeon and Levi pretend to make peace and then slaughter the city.',
    m: 'Vengeance multiplies wrong; Jacob later curses their anger (Genesis 49:5–7).', vt: ['justice'], w: ['vengeance', 'deceit'],
    hard: 'The narrative gives Dinah no voice, which many modern readers note; it shows wrong answered by greater wrong.' },
  { id: 'joseph', era: 'patriarchs', t: 'Joseph sold by his brothers', p: 'Genesis 37', v: 'Gen.37.28',
    x: 'Jacob’s favourite son, with his coat and his dreams, is hated by his brothers, who throw him into a pit and sell him for twenty pieces of silver to traders bound for Egypt.',
    m: 'Favouritism breeds resentment; envy can turn brothers into traffickers.', vt: ['patience'], w: ['envy', 'favouritism', 'pride'] },
  { id: 'tamar', era: 'patriarchs', t: 'Judah and Tamar', p: 'Genesis 38', v: 'Gen.38.26',
    x: 'Denied the levirate husband she is owed, the widow Tamar disguises herself and conceives by her father-in-law Judah, who, shown the proof, says, “She hath been more righteous than I.”',
    m: 'The powerful must own their injustice; Tamar becomes an ancestor of David and of Jesus (Matthew 1:3).', vt: ['justice', 'repentance', 'courage'] },
  { id: 'potiphar', era: 'patriarchs', t: 'Joseph and Potiphar’s wife', p: 'Genesis 39', v: 'Gen.39.9',
    x: 'A slave in Egypt, Joseph refuses his master’s wife: “how then can I do this great wickedness, and sin against God?” Falsely accused, he is imprisoned, yet prospers there.',
    m: 'Integrity costs something and is worth it; faithfulness in obscurity prepares for responsibility.', vt: ['integrity', 'chastity', 'faithfulness'], w: ['lust', 'false witness'] },
  { id: 'dreams', era: 'patriarchs', t: 'Joseph interprets Pharaoh’s dreams', p: 'Genesis 40–41', v: 'Gen.41.16',
    x: 'Joseph interprets the dreams of fat and lean cows as seven years of plenty and seven of famine, and is made governor to store grain for the coming famine.',
    m: 'Wisdom is a gift to be used for others; good stewardship saves lives in hard times.', vt: ['wisdom', 'stewardship', 'humility'] },
  { id: 'josephforgives', era: 'patriarchs', t: 'Joseph forgives his brothers', p: 'Genesis 42–45; 50:15–21', v: 'Gen.50.20',
    x: 'The brothers come to Egypt for food; Joseph tests whether they have changed, sees Judah offer himself for Benjamin, weeps and reveals himself: “ye thought evil against me; but God meant it unto good.”',
    m: 'Forgiveness is possible after real repentance; God can bring good out of evil without excusing it.', vt: ['forgiveness', 'reconciliation', 'repentance', 'providence'] },

  /* ── Exodus and wilderness ── */
  { id: 'midwives', era: 'exodus', t: 'The Hebrew midwives', p: 'Exodus 1:15–22', v: 'Exod.1.17',
    x: 'Pharaoh orders the midwives Shiphrah and Puah to kill Hebrew baby boys; they fear God and let them live.',
    m: 'The first recorded act of civil disobedience: conscience before an unjust command.', vt: ['courage', 'conscience', 'mercy'] },
  { id: 'basket', era: 'exodus', t: 'Moses in the basket', p: 'Exodus 2:1–10', v: 'Exod.2.10',
    x: 'Moses’ mother hides him in a basket among the reeds; Pharaoh’s daughter finds him, pities him and raises him as her son.',
    m: 'Compassion crosses lines of race and power; small acts of courage by women save the deliverer.', vt: ['compassion', 'courage'] },
  { id: 'bush', era: 'exodus', t: 'The burning bush', p: 'Exodus 3–4', v: 'Exod.3.14',
    x: 'A fugitive shepherd, Moses sees a bush that burns without being consumed; God reveals his name, “I AM THAT I AM,” and sends him to Pharaoh despite his objections.',
    m: 'God hears the cry of the oppressed; he calls the reluctant and promises his presence instead of their sufficiency.', vt: ['humility', 'obedience', 'courage'] },
  { id: 'plagues', era: 'exodus', t: 'The ten plagues', p: 'Exodus 7–11', v: 'Exod.9.16',
    x: 'Pharaoh refuses to let Israel go; water turns to blood, then frogs, gnats, flies, livestock disease, boils, hail, locusts and darkness follow, and Pharaoh hardens his heart each time.',
    m: 'Oppressive power that will not yield invites its own ruin; the plagues mock the gods of Egypt (Exodus 12:12).', vt: ['justice', 'humility'], w: ['hardness of heart', 'oppression'],
    hard: 'That God “hardened Pharaoh’s heart” has long been debated: Pharaoh first hardens his own heart, and the text describes both.' },
  { id: 'passover', era: 'exodus', t: 'The Passover', p: 'Exodus 12', v: 'Exod.12.13',
    x: 'Each household sacrifices a lamb and marks its doorposts with blood; the destroyer passes over them, the firstborn of Egypt die, and Israel leaves in haste with unleavened bread.',
    m: 'Deliverance is remembered every year in Judaism; Christians read Christ as the Passover lamb (1 Corinthians 5:7).', vt: ['obedience', 'remembrance', 'gratitude'],
    hard: 'The death of Egypt’s firstborn is among the hardest passages in Scripture; Jewish tradition spills drops of wine at the Seder for Egyptian suffering.' },
  { id: 'redsea', era: 'exodus', t: 'Crossing the Red Sea', p: 'Exodus 14–15', v: 'Exod.14.13',
    x: 'Trapped between Pharaoh’s army and the sea, Israel is told “stand still, and see the salvation of the LORD.” The waters part, Israel crosses, and the army is drowned. Miriam leads the song.',
    m: 'When there is no way, God makes one; freedom is received before it is earned.', vt: ['trust', 'courage', 'praise'] },
  { id: 'manna', era: 'exodus', t: 'Manna and quail', p: 'Exodus 16', v: 'Exod.16.4',
    x: 'In the desert the people grumble for Egypt’s food; God sends bread from heaven each morning, enough for each day, and a double portion before the Sabbath. Hoarded manna rots.',
    m: 'Daily dependence on God; enough is enough; rest is built into provision. Jesus calls himself the true bread (John 6).', vt: ['trust', 'contentment', 'gratitude'], w: ['grumbling', 'hoarding'] },
  { id: 'jethro', era: 'exodus', t: 'Jethro’s advice', p: 'Exodus 18', v: 'Exod.18.18',
    x: 'Moses judges the people alone from morning to evening; his father-in-law warns him he will wear himself out and tells him to appoint capable, honest leaders.',
    m: 'Wise leadership delegates; even prophets need advice from outsiders.', vt: ['humility', 'wisdom'] },
  { id: 'sinai', era: 'exodus', t: 'The Ten Commandments', p: 'Exodus 19–20', v: 'Exod.20.2',
    x: 'At Sinai, amid thunder and smoke, God gives the Ten Words, beginning not with a demand but with a reminder: “I am the LORD thy God, which have brought thee out of the land of Egypt.”',
    m: 'Law follows grace: commandments are the shape of life for a freed people; love of God and neighbour in concrete form.', vt: ['obedience', 'justice', 'reverence'] },
  { id: 'calf', era: 'exodus', t: 'The golden calf', p: 'Exodus 32–34', v: 'Exod.32.4',
    x: 'While Moses is on the mountain, the people make a golden calf and worship it. Moses breaks the tablets, then intercedes for the people; God reveals himself as “merciful and gracious, longsuffering.”',
    m: 'Impatience turns to idolatry; leaders must not give in to the crowd (Aaron); intercession and mercy follow judgement.', vt: ['patience', 'intercession', 'faithfulness'], w: ['idolatry', 'impatience'] },
  { id: 'spies', era: 'exodus', t: 'The twelve spies', p: 'Numbers 13–14', v: 'Num.14.9',
    x: 'Ten spies report giants and spread fear; Joshua and Caleb urge trust. The people refuse to enter, and that generation wanders forty years.',
    m: 'Fear is contagious and costly; courage rests on God’s promise, not on the size of the obstacle.', vt: ['courage', 'faith'], w: ['fear', 'unbelief'] },
  { id: 'korah', era: 'exodus', t: 'Korah’s rebellion', p: 'Numbers 16', v: 'Num.16.3',
    x: 'Korah and 250 leaders challenge Moses and Aaron; the earth opens and swallows the rebels.',
    m: 'Envy of another’s calling disguised as equality destroys community.', vt: ['humility', 'contentment'], w: ['envy', 'ambition'] },
  { id: 'serpent', era: 'exodus', t: 'The bronze serpent', p: 'Numbers 21:4–9', v: 'Num.21.8',
    x: 'Bitten by fiery serpents after grumbling, the people are told to look at a bronze serpent on a pole and live.',
    m: 'Healing comes by looking in trust to what God provides; Jesus applies it to his crucifixion (John 3:14). Hezekiah later destroys the serpent when it becomes an idol (2 Kings 18:4).', vt: ['faith', 'trust'], w: ['grumbling'] },
  { id: 'balaam', era: 'exodus', t: 'Balaam and the donkey', p: 'Numbers 22–24', v: 'Num.22.28',
    x: 'Hired to curse Israel, the prophet Balaam beats his donkey when it refuses to pass an angel he cannot see; the donkey speaks, and Balaam can only bless Israel.',
    m: 'God’s purposes cannot be bought; sometimes the humblest creature sees more than the expert.', vt: ['integrity', 'humility'], w: ['greed'] },
  { id: 'mosesdeath', era: 'exodus', t: 'The death of Moses', p: 'Deuteronomy 34', v: 'Deut.34.4',
    x: 'Forbidden to enter the land for striking the rock in anger (Numbers 20), Moses sees it from Mount Nebo, dies, and is buried by God in an unknown place.',
    m: 'Even the greatest leader is accountable; finishing one’s part faithfully matters more than seeing the end; leadership passes on.', vt: ['faithfulness', 'humility', 'acceptance'], w: ['anger'] },

  /* ── The land and the judges ── */
  { id: 'rahab', era: 'land', t: 'Rahab and the spies', p: 'Joshua 2; 6:22–25', v: 'Josh.2.11',
    x: 'Rahab, a prostitute of Jericho, hides Israel’s spies, confesses faith in their God and is spared with her family.',
    m: 'Faith can appear in unexpected people; Rahab is honoured in Hebrews 11 and named in Jesus’ genealogy.', vt: ['faith', 'courage', 'hospitality'] },
  { id: 'jericho', era: 'land', t: 'The walls of Jericho', p: 'Joshua 6', v: 'Josh.6.20',
    x: 'Israel marches around Jericho once a day for six days and seven times on the seventh; the priests blow trumpets, the people shout and the walls fall.',
    m: 'Victory is God’s gift, received through patient obedience rather than force.', vt: ['obedience', 'patience', 'faith'],
    hard: 'The command to destroy the inhabitants (herem) is one of the Bible’s most debated ethical problems. Readers explain it as hyperbolic war rhetoric, as a unique judgement, or as a text later revelation corrects; the archaeology of Jericho’s walls at this date is also disputed.' },
  { id: 'achan', era: 'land', t: 'Achan’s sin', p: 'Joshua 7', v: 'Josh.7.21',
    x: 'Achan secretly takes plunder from Jericho; Israel is defeated at Ai until his theft is exposed: “I coveted them, and took them.”',
    m: 'Hidden sin harms the whole community; coveting leads to taking.', vt: ['honesty', 'integrity'], w: ['greed', 'deceit'] },
  { id: 'joshua24', era: 'land', t: 'Joshua’s farewell', p: 'Joshua 24', v: 'Josh.24.15',
    x: 'At Shechem the aged Joshua recounts God’s acts and calls the people to choose: “as for me and my house, we will serve the LORD.”',
    m: 'Faith must be chosen by each generation; leaders lead by their own example.', vt: ['commitment', 'faithfulness'] },
  { id: 'deborah', era: 'land', t: 'Deborah and Jael', p: 'Judges 4–5', v: 'Judg.4.9',
    x: 'The prophet and judge Deborah sends Barak against Sisera’s chariots; the victory goes to a woman, Jael, who kills the fleeing general. The Song of Deborah celebrates it.',
    m: 'God raises leaders without regard to rank or gender; hesitation forfeits honour.', vt: ['courage', 'leadership', 'faith'] },
  { id: 'gideon', era: 'land', t: 'Gideon and the three hundred', p: 'Judges 6–8', v: 'Judg.7.2',
    x: 'Gideon, hiding from raiders, is called “mighty man of valour,” asks for signs with a fleece, and defeats Midian with 300 men carrying trumpets and torches. He refuses a crown, but his golden ephod becomes a snare.',
    m: 'God works through weakness so that no one boasts; even a faithful leader can leave a harmful legacy.', vt: ['courage', 'humility', 'faith'], w: ['fear', 'idolatry'] },
  { id: 'jephthah', era: 'land', t: 'Jephthah’s vow', p: 'Judges 11', v: 'Judg.11.35',
    x: 'The outcast warrior Jephthah vows to sacrifice whatever first comes out of his house if he wins; his only daughter comes out dancing.',
    m: 'Rash vows and pagan ideas of bargaining with God end in tragedy; the story is a warning, not a model.', vt: ['wisdom'], w: ['rashness'],
    hard: 'Whether he killed her or dedicated her to lifelong virginity is debated; Jewish and Christian commentators widely condemn the vow.' },
  { id: 'samson', era: 'land', t: 'Samson and Delilah', p: 'Judges 13–16', v: 'Judg.16.28',
    x: 'Dedicated from birth and given great strength, Samson squanders his gifts in lust and revenge, reveals the secret of his hair to Delilah, is blinded by the Philistines, and in a last prayer pulls down their temple.',
    m: 'Great gifts without self-control lead to ruin; God can still answer the humbled.', vt: ['self-control', 'repentance'], w: ['lust', 'pride', 'vengeance'] },
  { id: 'levite', era: 'land', t: 'The Levite’s concubine', p: 'Judges 19–21', v: 'Judg.21.25',
    x: 'A Levite’s concubine is abused to death in Gibeah; he dismembers her body to summon Israel, and civil war nearly destroys the tribe of Benjamin.',
    m: 'The book’s verdict: “every man did that which was right in his own eyes.” Without justice, a society devours its weakest.', vt: ['justice'], w: ['cruelty', 'lawlessness'],
    hard: 'Phyllis Trible called this one of the “texts of terror.” Its deliberate echoes of Sodom show Israel becoming what it condemned.' },
  { id: 'ruth', era: 'land', t: 'Ruth and Naomi', p: 'Ruth 1–4', v: 'Ruth.1.16',
    x: 'Widowed, the Moabite Ruth refuses to leave her mother-in-law: “whither thou goest, I will go.” She gleans in Boaz’s fields, and Boaz, acting as kinsman-redeemer, marries her. She becomes David’s great-grandmother.',
    m: 'Loyal love (ḥesed) crosses national boundaries; ordinary kindness and justice carry God’s purposes.', vt: ['loyalty', 'kindness', 'generosity'] },

  /* ── The kingdom ── */
  { id: 'hannah', era: 'kingdom', t: 'Hannah’s prayer', p: '1 Samuel 1–2', v: '1Sam.1.27',
    x: 'Childless and taunted, Hannah prays so intensely that the priest thinks she is drunk; she bears Samuel, gives him to God’s service and sings a song of reversal echoed in Mary’s Magnificat.',
    m: 'God hears honest, anguished prayer; he lifts the lowly.', vt: ['prayer', 'perseverance', 'gratitude'] },
  { id: 'samuel', era: 'kingdom', t: 'The call of Samuel', p: '1 Samuel 3', v: '1Sam.3.10',
    x: 'The boy Samuel hears his name in the night and, taught by Eli, answers, “Speak; for thy servant heareth.” His first message is judgement on Eli’s corrupt sons.',
    m: 'Listening is the beginning of faith; truth must be spoken even to one’s mentor.', vt: ['attentiveness', 'honesty', 'courage'] },
  { id: 'saulking', era: 'kingdom', t: 'Saul’s disobedience', p: '1 Samuel 13; 15', v: '1Sam.15.22',
    x: 'Israel’s first king offers sacrifice impatiently and later spares what God commanded to be destroyed; Samuel tells him, “to obey is better than sacrifice,” and the kingdom is torn from him.',
    m: 'Religious show cannot replace obedience; fear of people corrupts leadership.', vt: ['obedience', 'integrity'], w: ['impatience', 'people-pleasing'] },
  { id: 'davidanointed', era: 'kingdom', t: 'David anointed', p: '1 Samuel 16', v: '1Sam.16.7',
    x: 'Samuel looks over Jesse’s tall sons, but God says, “the LORD looketh on the heart.” The youngest, a shepherd boy, is anointed.',
    m: 'God judges by character, not appearance.', vt: ['humility', 'integrity'] },
  { id: 'goliath', era: 'kingdom', t: 'David and Goliath', p: '1 Samuel 17', v: '1Sam.17.45',
    x: 'For forty days the giant Goliath defies Israel; the shepherd David refuses Saul’s armour, takes five stones and a sling, and fells him: “I come to thee in the name of the LORD of hosts.”',
    m: 'Courage comes from trust, not size; faithfulness in small things (guarding sheep) prepares for great ones.', vt: ['courage', 'faith', 'resourcefulness'], w: ['fear', 'arrogance'] },
  { id: 'jonathan', era: 'kingdom', t: 'David and Jonathan', p: '1 Samuel 18–20', v: '1Sam.18.3',
    x: 'Saul’s son Jonathan loves David “as his own soul,” makes a covenant with him and protects him from his father’s jealousy, though it costs him the throne.',
    m: 'True friendship is loyal, selfless and rejoices in the other’s good.', vt: ['loyalty', 'friendship', 'selflessness'], w: ['jealousy'] },
  { id: 'sparesaul', era: 'kingdom', t: 'David spares Saul', p: '1 Samuel 24; 26', v: '1Sam.24.6',
    x: 'Hunted by Saul, David twice has the king in his power and refuses to kill “the LORD’s anointed,” cutting off only the corner of his robe.',
    m: 'Restraint and respect for rightful authority, even an unjust one; leave vengeance to God.', vt: ['self-control', 'mercy', 'respect'], w: ['vengeance'] },
  { id: 'abigail', era: 'kingdom', t: 'Abigail', p: '1 Samuel 25', v: '1Sam.25.33',
    x: 'Nabal insults David’s men; his wife Abigail rides out with gifts and wise words, turning David from bloodshed.',
    m: 'Wisdom and humility defuse violence; a peacemaker can save the powerful from themselves.', vt: ['wisdom', 'peacemaking', 'courage'], w: ['foolishness', 'anger'] },
  { id: 'endor', era: 'kingdom', t: 'Saul and the medium of Endor; Saul’s death', p: '1 Samuel 28; 31', v: '1Sam.28.15',
    x: 'Desperate before battle, Saul consults a medium he had banned; Samuel’s figure foretells his death. Wounded on Mount Gilboa, Saul falls on his own sword, and Jonathan dies with him.',
    m: 'A life of disobedience ends in desperation; David’s lament “how are the mighty fallen” honours even his enemy.', vt: ['repentance'], w: ['disobedience', 'despair', 'occultism'] },
  { id: 'ark', era: 'kingdom', t: 'Uzzah and the ark', p: '2 Samuel 6', v: '2Sam.6.14',
    x: 'Uzzah touches the ark to steady it and dies; later David brings the ark into Jerusalem, dancing with all his might, and is mocked by Michal.',
    m: 'God’s holiness is not to be handled carelessly; joy in worship need not care about dignity.', vt: ['reverence', 'joy', 'humility'],
    hard: 'Uzzah’s death troubles readers; the text notes the ark was being carried on a cart against the instructions for carrying it (Numbers 4:15).' },
  { id: 'mephibosheth', era: 'kingdom', t: 'David and Mephibosheth', p: '2 Samuel 9', v: '2Sam.9.7',
    x: 'David seeks out Jonathan’s lame son, restores his land and gives him a place at the king’s table “for Jonathan thy father’s sake.”',
    m: 'Kindness keeps covenant beyond death; grace seats the overlooked at the table.', vt: ['kindness', 'loyalty', 'grace'] },
  { id: 'bathsheba', era: 'kingdom', t: 'David and Bathsheba', p: '2 Samuel 11–12', v: '2Sam.12.7',
    x: 'At home while his army fights, David takes Bathsheba, then arranges her husband Uriah’s death. The prophet Nathan tells a parable of a rich man stealing a poor man’s lamb and confronts him: “Thou art the man.” David repents (Psalm 51), but the child dies and violence haunts his house.',
    m: 'Idleness and power invite sin; one sin leads to cover-up and murder; truth must be spoken to power; repentance is real, though consequences remain.', vt: ['repentance', 'honesty', 'courage'], w: ['lust', 'abuse of power', 'deceit'] },
  { id: 'absalom', era: 'kingdom', t: 'Absalom’s rebellion', p: '2 Samuel 13–18', v: '2Sam.18.33',
    x: 'After his sister Tamar is raped by their half-brother Amnon and David does nothing, Absalom kills Amnon, later steals the people’s hearts and revolts. He dies caught by his hair in a tree, and David weeps, “O my son Absalom.”',
    m: 'A father’s failure to do justice festers into catastrophe; love for a rebellious child is real and grievous.', vt: ['justice', 'love'], w: ['passivity', 'vengeance', 'ambition'] },
  { id: 'solomonwisdom', era: 'kingdom', t: 'Solomon asks for wisdom', p: '1 Kings 3', v: '1Kgs.3.9',
    x: 'Offered anything, the young king asks for “an understanding heart” to judge the people. God grants it with riches besides, and Solomon resolves two women’s claim to one baby by threatening to divide it.',
    m: 'Wisdom to serve others is the best request; justice can see through deceit to the truth of the heart.', vt: ['wisdom', 'humility', 'justice'] },
  { id: 'temple', era: 'kingdom', t: 'The temple dedicated', p: '1 Kings 8', v: '1Kgs.8.27',
    x: 'Solomon dedicates the temple, yet prays, “the heaven and heaven of heavens cannot contain thee; how much less this house.”',
    m: 'Sacred places are gifts, not containers for God; prayer includes the foreigner (1 Kings 8:41–43).', vt: ['reverence', 'humility', 'prayer'] },
  { id: 'solomonfall', era: 'kingdom', t: 'Solomon’s fall', p: '1 Kings 10–11', v: '1Kgs.11.4',
    x: 'Solomon multiplies gold, horses and wives, exactly as Deuteronomy 17 warned kings not to; his foreign wives turn his heart to other gods, he builds shrines for them and uses forced labour. The kingdom splits after his death.',
    m: 'Wisdom does not protect against a divided heart; wealth and indulgence erode faithfulness slowly; leaders’ excesses burden the people (1 Kings 12:4). Ecclesiastes reflects on this emptiness.', vt: ['faithfulness', 'self-control'], w: ['idolatry', 'greed', 'lust', 'pride'] },
  { id: 'rehoboam', era: 'kingdom', t: 'Rehoboam and the divided kingdom', p: '1 Kings 12', v: '1Kgs.12.7',
    x: 'Solomon’s son rejects the elders’ advice to serve the people and follows his young friends: “my little finger shall be thicker than my father’s loins.” Ten tribes break away.',
    m: 'Leaders who serve are followed; arrogance divides nations.', vt: ['humility', 'servant leadership'], w: ['arrogance'] },
  { id: 'elijahravens', era: 'kingdom', t: 'Elijah, the ravens and the widow', p: '1 Kings 17', v: '1Kgs.17.16',
    x: 'In a drought Elijah is fed by ravens, then by a foreign widow who shares her last flour; her jar does not run out, and her son is restored to life.',
    m: 'God provides through unlikely means; generosity in poverty is met with provision. Jesus cites her in Luke 4:26.', vt: ['generosity', 'faith', 'hospitality'] },
  { id: 'carmel', era: 'kingdom', t: 'Elijah on Mount Carmel', p: '1 Kings 18', v: '1Kgs.18.21',
    x: 'Elijah challenges 450 prophets of Baal: “How long halt ye between two opinions?” Their god does not answer; fire falls on Elijah’s soaked altar.',
    m: 'Divided loyalty is not neutral; the living God answers where idols cannot.', vt: ['courage', 'faith', 'conviction'], w: ['idolatry', 'indecision'],
    hard: 'Elijah then has the prophets of Baal killed; some readers note that his collapse into despair follows immediately.' },
  { id: 'stillvoice', era: 'kingdom', t: 'Elijah and the still small voice', p: '1 Kings 19', v: '1Kgs.19.12',
    x: 'Threatened by Jezebel, Elijah flees, asks to die, is given sleep and food by an angel, and at Horeb hears God not in wind, earthquake or fire but in “a still small voice.”',
    m: 'Even great prophets burn out; rest and food come first; God speaks quietly and is never as alone as we feel (seven thousand faithful remain).', vt: ['rest', 'hope', 'attentiveness'], w: ['despair'] },
  { id: 'naboth', era: 'kingdom', t: 'Naboth’s vineyard', p: '1 Kings 21', v: '1Kgs.21.19',
    x: 'King Ahab covets Naboth’s vineyard; Queen Jezebel arranges false witnesses and Naboth is stoned. Elijah confronts Ahab, who humbles himself.',
    m: 'The powerful who seize the property of the poor stand under God’s judgement; property rights protect the weak.', vt: ['justice', 'repentance'], w: ['covetousness', 'false witness', 'abuse of power'] },
  { id: 'elisha', era: 'kingdom', t: 'Elijah’s chariot and Elisha’s double portion', p: '2 Kings 2', v: '2Kgs.2.9',
    x: 'Elisha refuses to leave his master and asks for a double portion of his spirit; Elijah is taken up by a whirlwind with chariots of fire, and Elisha takes up his mantle.',
    m: 'Faithful apprenticeship and persistence; leadership passes to those who stay.', vt: ['loyalty', 'perseverance'] },
  { id: 'naaman', era: 'kingdom', t: 'Naaman healed', p: '2 Kings 5', v: '2Kgs.5.13',
    x: 'An enemy general with leprosy is told by an Israelite slave girl to see Elisha; offended to be told to wash in the Jordan seven times, he is persuaded by his servants, is healed, and Elisha refuses payment. Gehazi’s greed is punished.',
    m: 'Pride resists simple obedience; grace is free and cannot be bought; mercy reaches enemies (Luke 4:27).', vt: ['humility', 'obedience', 'integrity'], w: ['pride', 'greed'] },
  { id: 'hezekiah', era: 'kingdom', t: 'Hezekiah and the Assyrians', p: '2 Kings 18–20', v: '2Kgs.19.19',
    x: 'Besieged by Sennacherib, whose envoy mocks Israel’s God, Hezekiah spreads the letter before the LORD and prays; the Assyrian army withdraws. Later, sick, he prays and is given fifteen more years, but shows his treasures to Babylon’s envoys.',
    m: 'Bring threats to God in prayer; deliverance is not a licence for pride.', vt: ['prayer', 'trust'], w: ['pride'] },
  { id: 'josiah', era: 'kingdom', t: 'Josiah finds the book of the law', p: '2 Kings 22–23', v: '2Kgs.22.11',
    x: 'Repairing the temple, workers find the book of the law; young King Josiah tears his clothes, consults the prophetess Huldah and leads a sweeping reform and Passover.',
    m: 'Scripture rediscovered renews a nation; a tender heart responds to truth with action.', vt: ['repentance', 'reform', 'humility'] },

  /* ── Prophets, exile and return ── */
  { id: 'job', era: 'prophets', t: 'Job', p: 'Job 1–42', v: 'Job.1.21',
    x: 'A righteous man loses his children, wealth and health; refusing to curse God, he also refuses his friends’ claim that he must deserve it, and demands an answer. God speaks from the whirlwind, and Job is restored.',
    m: 'Suffering is not always punishment; honest lament is permitted; God is greater than our explanations. The friends are rebuked for speaking wrongly about God.', vt: ['perseverance', 'honesty', 'humility', 'faith'], w: ['judgementalism'] },
  { id: 'isaiahcall', era: 'prophets', t: 'Isaiah’s vision', p: 'Isaiah 6', v: 'Isa.6.8',
    x: 'Isaiah sees the LORD enthroned and seraphim crying “Holy, holy, holy”; confessing his unclean lips, he is cleansed by a burning coal and answers, “Here am I; send me.”',
    m: 'Awe leads to confession, confession to cleansing, cleansing to mission.', vt: ['reverence', 'humility', 'obedience'] },
  { id: 'jeremiah', era: 'prophets', t: 'Jeremiah buys a field', p: 'Jeremiah 32', v: 'Jer.32.15',
    x: 'Imprisoned while Babylon besieges Jerusalem, Jeremiah buys a field and seals the deed: “Houses and fields and vineyards shall be possessed again in this land.”',
    m: 'Hope acts in the middle of disaster; faithfulness invests in a future it may not see.', vt: ['hope', 'faith', 'perseverance'] },
  { id: 'exile', era: 'prophets', t: 'The fall of Jerusalem and the letter to the exiles', p: '2 Kings 25; Jeremiah 29', v: 'Jer.29.7',
    x: 'Babylon destroys the temple (587 BC) and deports the people. Jeremiah writes to the exiles: build houses, plant gardens, “seek the peace of the city” where you are.',
    m: 'Faith survives the loss of land and temple; God’s people can seek the good of a foreign city.', vt: ['hope', 'resilience', 'public good'] },
  { id: 'drybones', era: 'prophets', t: 'The valley of dry bones', p: 'Ezekiel 37', v: 'Ezek.37.5',
    x: 'Ezekiel sees a valley of bones come together, take on flesh and live when the breath (rûaḥ) enters them: a vision of exiled Israel restored.',
    m: 'No situation is beyond God’s power to revive.', vt: ['hope'] },
  { id: 'furnace', era: 'prophets', t: 'The fiery furnace', p: 'Daniel 3', v: 'Dan.3.18',
    x: 'Shadrach, Meshach and Abednego refuse to bow to Nebuchadnezzar’s image: God can save us, “but if not,” we will not serve your gods. A fourth figure walks with them in the fire.',
    m: 'Faithfulness does not depend on rescue; conscience before the state.', vt: ['courage', 'faithfulness', 'conscience'], w: ['idolatry', 'conformity'] },
  { id: 'handwriting', era: 'prophets', t: 'The writing on the wall', p: 'Daniel 5', v: 'Dan.5.27',
    x: 'At a drunken feast using the temple vessels, a hand writes on the wall; Daniel reads it: “Thou art weighed in the balances, and art found wanting.” Babylon falls that night.',
    m: 'Arrogant power is measured and found wanting.', vt: ['humility', 'reverence'], w: ['pride', 'sacrilege'] },
  { id: 'lions', era: 'prophets', t: 'Daniel in the lions’ den', p: 'Daniel 6', v: 'Dan.6.10',
    x: 'Jealous officials trap Daniel with a decree against prayer; he keeps praying three times a day with his windows open, is thrown to the lions and is preserved.',
    m: 'Habitual faithfulness under pressure; integrity so complete that enemies can only attack his faith.', vt: ['faithfulness', 'integrity', 'courage', 'prayer'], w: ['envy'] },
  { id: 'jonah', era: 'prophets', t: 'Jonah', p: 'Jonah 1–4', v: 'Jonah.4.11',
    x: 'Sent to Nineveh, Jonah flees by ship, is thrown overboard and swallowed by a great fish, prays and is spat out. He preaches, Nineveh repents, and Jonah sulks that God is merciful.',
    m: 'You cannot outrun God; God’s mercy extends to Israel’s enemies; the prophet is the last to learn compassion.', vt: ['obedience', 'mercy', 'compassion', 'repentance'], w: ['prejudice', 'self-pity'] },
  { id: 'esther', era: 'prophets', t: 'Esther', p: 'Esther 1–10', v: 'Esth.4.14',
    x: 'A Jewish orphan becomes queen of Persia; when Haman plots genocide, her cousin Mordecai urges her, “who knoweth whether thou art come to the kingdom for such a time as this?” She risks her life to approach the king, and the plot is reversed.',
    m: 'Providence works through courage in hidden places; privilege carries responsibility. The origin of Purim.', vt: ['courage', 'responsibility', 'wisdom'], w: ['pride', 'hatred'] },
  { id: 'nehemiah', era: 'prophets', t: 'Nehemiah rebuilds the walls', p: 'Nehemiah 1–6; 8', v: 'Neh.4.14',
    x: 'A cupbearer in Persia weeps for Jerusalem, prays, asks the king’s leave, and organises the people to rebuild the walls in 52 days despite ridicule and threats, with tools in one hand and weapons in the other. Ezra reads the law to the people.',
    m: 'Prayer and planning go together; perseverance under opposition; leaders refuse to profit from office (5:14–15).', vt: ['perseverance', 'leadership', 'prayer', 'integrity'] },

  /* ── Deuterocanon ── */
  { id: 'tobit', era: 'deutero', t: 'Tobit and Tobias', p: 'Tobit 1–14', v: 'Tob.12.8',
    x: 'Tobit, a devout exile who buries the dead at risk to himself, is blinded; his son Tobias travels with a companion who is the angel Raphael in disguise, marries Sarah, and returns to heal his father.',
    m: 'Almsgiving, burial of the dead, prayer and filial love are honoured; God’s help often comes in disguise.', vt: ['charity', 'faithfulness', 'family love'] },
  { id: 'judith', era: 'deutero', t: 'Judith', p: 'Judith 8–16', v: 'Jdt.8.17',
    x: 'When her city is about to surrender to the Assyrian general Holofernes, the widow Judith rebukes the elders for testing God, goes into the enemy camp and beheads the general.',
    m: 'Courage and trust when leaders lose heart; God saves through the weak.', vt: ['courage', 'faith', 'wisdom'] },
  { id: 'susanna', era: 'deutero', t: 'Susanna and the elders', p: 'Daniel 13 (Catholic and Orthodox Bibles)',
    x: 'Two elders try to blackmail the virtuous Susanna; she refuses and is condemned on their false testimony until young Daniel questions them separately and their stories contradict.',
    m: 'Integrity under false accusation; justice requires cross-examining witnesses; the respected can be corrupt.', vt: ['integrity', 'chastity', 'justice'], w: ['lust', 'false witness'] },
  { id: 'maccabees', era: 'deutero', t: 'The Maccabees and Hanukkah', p: '1 Maccabees 1–4', v: '1Macc.4.59',
    x: 'When Antiochus IV outlaws Judaism and desecrates the temple, the priest Mattathias and his sons revolt; Judas Maccabeus retakes Jerusalem and rededicates the temple (164 BC), remembered at Hanukkah.',
    m: 'Faithfulness under persecution; restored worship is celebrated with light.', vt: ['courage', 'faithfulness', 'perseverance'] },
  { id: 'sevenbrothers', era: 'deutero', t: 'The mother and seven sons', p: '2 Maccabees 7', v: '2Macc.12.46',
    x: 'A mother watches her seven sons tortured to death for refusing pork; she encourages each to die faithfully in hope of the resurrection.',
    m: 'Hope in resurrection gives courage to the persecuted; Hebrews 11:35 alludes to such martyrs.', vt: ['courage', 'hope', 'faithfulness'] },

  /* ── The life of Jesus ── */
  { id: 'annunciation', era: 'jesus', t: 'The annunciation', p: 'Luke 1:26–56', v: 'Luke.1.38',
    x: 'The angel Gabriel tells Mary she will bear a son by the Holy Spirit; she answers, “be it unto me according to thy word,” and sings the Magnificat: God “hath put down the mighty … and exalted them of low degree.”',
    m: 'Faith as willing consent; God’s favour rests on the lowly.', vt: ['faith', 'humility', 'obedience'] },
  { id: 'nativity', era: 'jesus', t: 'The nativity', p: 'Luke 2:1–20; Matthew 1–2', v: 'Luke.2.14',
    x: 'Jesus is born in Bethlehem and laid in a manger because there is no room; angels announce him to shepherds, and later magi from the east bring gifts while Herod plots to kill him.',
    m: 'God comes in poverty and weakness; the outsiders (shepherds, foreigners) welcome him first while power feels threatened.', vt: ['humility', 'joy', 'worship'], w: ['fear of losing power'] },
  { id: 'temple12', era: 'jesus', t: 'The boy Jesus in the temple', p: 'Luke 2:41–52', v: 'Luke.2.49',
    x: 'At twelve, Jesus stays behind in the temple, listening to and questioning the teachers; found after three days, he returns home and is obedient to his parents.',
    m: 'Growth “in wisdom and stature, and in favour with God and man”; learning by questions.', vt: ['wisdom', 'obedience', 'curiosity'] },
  { id: 'baptism', era: 'jesus', t: 'The baptism of Jesus', p: 'Matthew 3', v: 'Matt.3.17',
    x: 'John the Baptist calls Israel to repentance in the Jordan; Jesus is baptised, the Spirit descends like a dove and a voice says, “This is my beloved Son.”',
    m: 'Jesus identifies with sinners; identity and belovedness come before ministry.', vt: ['humility', 'repentance'] },
  { id: 'temptation', era: 'jesus', t: 'The temptation in the wilderness', p: 'Matthew 4:1–11', v: 'Matt.4.4',
    x: 'After forty days of fasting, Jesus is tempted to turn stones into bread, to throw himself from the temple, and to worship the devil for the kingdoms of the world. He answers each from Deuteronomy.',
    m: 'Temptation targets appetite, spectacle and power; Scripture and trust answer it.', vt: ['self-control', 'faithfulness', 'humility'], w: ['appetite', 'pride', 'lust for power'] },
  { id: 'cana', era: 'jesus', t: 'The wedding at Cana', p: 'John 2:1–11', v: 'John.2.11',
    x: 'When the wine runs out at a village wedding, Jesus has servants fill water jars, and the water becomes the best wine.',
    m: 'Jesus’ first sign is generous joy at a celebration; Mary’s “whatsoever he saith unto you, do it.”', vt: ['joy', 'generosity', 'trust'] },
  { id: 'nicodemus', era: 'jesus', t: 'Nicodemus by night', p: 'John 3:1–21', v: 'John.3.16',
    x: 'A Pharisee leader comes secretly at night; Jesus tells him he must be “born again” (or “from above”) and speaks of God so loving the world that he gave his Son.',
    m: 'Spiritual rebirth is God’s gift; Nicodemus later defends Jesus and helps bury him.', vt: ['seeking', 'courage'] },
  { id: 'samaritan', era: 'jesus', t: 'The woman at the well', p: 'John 4', v: 'John.4.14',
    x: 'Jesus asks a Samaritan woman for water, breaking ethnic and gender barriers, offers her “living water,” and knows her history; she becomes a messenger to her town.',
    m: 'No one is beyond welcome; honesty about one’s life opens the way to new life.', vt: ['acceptance', 'honesty', 'witness'], w: ['prejudice'] },
  { id: 'sermon', era: 'jesus', t: 'The Sermon on the Mount', p: 'Matthew 5–7', v: 'Matt.5.44',
    x: 'Jesus blesses the poor in spirit, the meek and the merciful; teaches love of enemies, secret prayer and giving, the Lord’s Prayer, not worrying, not judging, the Golden Rule; and ends with the house built on rock.',
    m: 'The heart of Christian ethics: righteousness of the heart, not only of action; doing, not only hearing.', vt: ['mercy', 'humility', 'peacemaking', 'love of enemies', 'trust'], w: ['hypocrisy', 'anxiety', 'judgementalism'] },
  { id: 'storm', era: 'jesus', t: 'Calming the storm', p: 'Mark 4:35–41', v: 'Mark.4.40',
    x: 'In a violent storm Jesus sleeps; the terrified disciples wake him, he rebukes the wind and sea, and asks, “why are ye so fearful?”',
    m: 'Faith in the storm; fear and faith compete.', vt: ['trust', 'peace'], w: ['fear'] },
  { id: 'legion', era: 'jesus', t: 'The Gerasene demoniac', p: 'Mark 5:1–20', v: 'Mark.5.19',
    x: 'A man living among tombs, chained and self-harming, is freed of “Legion”; the townspeople, having lost their pigs, ask Jesus to leave, and the man becomes a witness.',
    m: 'No one is beyond restoration; communities sometimes prefer their losses counted in property to a neighbour healed.', vt: ['compassion', 'witness'], w: ['fear', 'materialism'] },
  { id: 'jairus', era: 'jesus', t: 'Jairus’s daughter and the woman who touched his cloak', p: 'Mark 5:21–43', v: 'Mark.5.34',
    x: 'On the way to a dying girl, Jesus stops for an outcast woman with twelve years of bleeding who touched his cloak; then he raises the girl: “Talitha cumi.”',
    m: 'Jesus has time for the unclean and overlooked; faith reaches out.', vt: ['faith', 'compassion', 'patience'] },
  { id: 'feeding', era: 'jesus', t: 'Feeding the five thousand', p: 'John 6:1–14', v: 'John.6.9',
    x: 'A boy’s five loaves and two fish feed a vast crowd, with twelve baskets left over.',
    m: 'Small offerings given to God are multiplied; nothing is wasted.', vt: ['generosity', 'trust', 'gratitude'] },
  { id: 'water', era: 'jesus', t: 'Walking on water', p: 'Matthew 14:22–33', v: 'Matt.14.31',
    x: 'Jesus comes to the disciples across the lake at night; Peter walks toward him, sees the wind, begins to sink and is caught: “O thou of little faith, wherefore didst thou doubt?”',
    m: 'Courage to step out; looking at the storm rather than at Christ brings sinking; rescue is near.', vt: ['courage', 'faith'], w: ['doubt'] },
  { id: 'adulteress', era: 'jesus', t: 'The woman taken in adultery', p: 'John 7:53–8:11', v: 'John.8.7',
    x: 'Accusers bring a woman to be stoned; Jesus writes on the ground and says, “He that is without sin among you, let him first cast a stone.” They leave, and he tells her, “go, and sin no more.”',
    m: 'Mercy and moral seriousness together; self-righteous accusers are exposed.', vt: ['mercy', 'humility', 'repentance'], w: ['self-righteousness', 'hypocrisy'] },
  { id: 'transfiguration', era: 'jesus', t: 'The transfiguration', p: 'Matthew 17:1–9', v: 'Matt.17.5',
    x: 'On a mountain Jesus shines with light and speaks with Moses and Elijah; a voice says, “hear ye him.”',
    m: 'Glory glimpsed strengthens for the road to the cross; the Law and the Prophets point to him.', vt: ['awe', 'attentiveness'] },
  { id: 'children', era: 'jesus', t: 'Jesus blesses the children', p: 'Mark 10:13–16', v: 'Mark.10.14',
    x: 'The disciples turn away parents bringing children; Jesus is indignant: “Suffer the little children to come unto me.”',
    m: 'The kingdom is received with childlike trust; the least are welcomed first.', vt: ['humility', 'trust', 'welcome'] },
  { id: 'richruler', era: 'jesus', t: 'The rich young ruler', p: 'Mark 10:17–27', v: 'Mark.10.21',
    x: 'A man who has kept the commandments asks how to inherit eternal life; Jesus, “beholding him loved him,” tells him to sell all and follow, and he goes away grieving.',
    m: 'Possessions can possess us; love sometimes asks everything.', vt: ['generosity', 'detachment'], w: ['greed', 'attachment'] },
  { id: 'martha', era: 'jesus', t: 'Martha and Mary', p: 'Luke 10:38–42', v: 'Luke.10.42',
    x: 'Martha is busy serving while her sister Mary sits at Jesus’ feet; Jesus tells Martha she is anxious about many things, but Mary has chosen the good part.',
    m: 'Attention to God before activity for God; a woman welcomed as a disciple.', vt: ['attentiveness', 'devotion'], w: ['anxiety', 'busyness'] },
  { id: 'zacchaeus', era: 'jesus', t: 'Zacchaeus', p: 'Luke 19:1–10', v: 'Luke.19.8',
    x: 'A rich chief tax collector climbs a tree to see Jesus, who invites himself to his house; Zacchaeus gives half his goods to the poor and repays fourfold anyone he cheated.',
    m: 'Being welcomed leads to repentance; real repentance makes restitution.', vt: ['repentance', 'generosity', 'justice'] },
  { id: 'lazarus', era: 'jesus', t: 'The raising of Lazarus', p: 'John 11', v: 'John.11.25',
    x: 'Jesus arrives four days after his friend’s death, weeps with the sisters, says, “I am the resurrection, and the life,” and calls Lazarus out of the tomb. The miracle prompts the plot to kill Jesus.',
    m: 'Jesus grieves with the grieving; death is not the last word.', vt: ['compassion', 'hope', 'faith'] },
  { id: 'entry', era: 'jesus', t: 'The triumphal entry and the cleansing of the temple', p: 'Mark 11', v: 'Mark.11.17',
    x: 'Jesus rides into Jerusalem on a donkey to the crowd’s hosannas, then overturns the money-changers’ tables: “My house shall be called of all nations the house of prayer.”',
    m: 'A king of peace, not war; zeal against religion turned into business.', vt: ['humility', 'righteous anger', 'justice'], w: ['exploitation'] },
  { id: 'widowmite', era: 'jesus', t: 'The widow’s mite', p: 'Mark 12:41–44', v: 'Mark.12.43',
    x: 'Watching people give at the temple, Jesus praises a poor widow’s two small coins above the rich gifts: she gave “all her living.”',
    m: 'God measures a gift by its cost, not its size.', vt: ['generosity', 'faith', 'sacrifice'] },
  { id: 'feet', era: 'jesus', t: 'The washing of the feet and the Last Supper', p: 'John 13; Mark 14:12–26', v: 'John.13.14',
    x: 'At the Passover meal Jesus washes his disciples’ feet, gives the bread and cup as his body and blood, foretells Judas’s betrayal and Peter’s denial, and gives the “new commandment” to love one another.',
    m: 'Greatness is service; the meal Christians share ever since.', vt: ['humility', 'service', 'love'] },
  { id: 'gethsemane', era: 'jesus', t: 'Gethsemane and the arrest', p: 'Mark 14:32–52', v: 'Mark.14.36',
    x: 'In anguish Jesus prays, “not what I will, but what thou wilt,” while his friends sleep; Judas betrays him with a kiss, and the disciples flee.',
    m: 'Honest anguish and surrender together; the failure of friends is not the end.', vt: ['surrender', 'prayer', 'courage'], w: ['betrayal', 'cowardice'] },
  { id: 'peterdenial', era: 'jesus', t: 'Peter’s denial', p: 'Mark 14:66–72; John 21:15–19', v: 'John.21.17',
    x: 'Peter, who swore he would die for Jesus, denies knowing him three times before the cock crows, and weeps. After the resurrection Jesus asks him three times, “lovest thou me?” and restores him.',
    m: 'Bold promises fail under fear; restoration is offered to the repentant, and failure can be the start of humble leadership.', vt: ['repentance', 'forgiveness', 'humility'], w: ['fear', 'overconfidence'] },
  { id: 'judas', era: 'jesus', t: 'Judas', p: 'Matthew 26:14–16; 27:3–10', v: 'Matt.27.4',
    x: 'One of the Twelve agrees to hand Jesus over for thirty pieces of silver; afterwards he returns the money, “I have sinned in that I have betrayed the innocent blood,” and hangs himself.',
    m: 'Greed and disillusionment can corrupt the closest follower; remorse without hope ends in despair, unlike Peter’s repentance. See the unit on the Twelve and Judas.', vt: ['repentance'], w: ['betrayal', 'greed', 'despair'] },
  { id: 'trial', era: 'jesus', t: 'The trial before Pilate', p: 'John 18:28–19:16', v: 'John.18.38',
    x: 'Pilate finds no fault in Jesus, asks “What is truth?”, offers to release him, and finally gives in to the crowd, washing his hands (Matthew 27:24). Barabbas is freed.',
    m: 'Knowing the right and failing to do it under pressure; washing one’s hands does not remove responsibility.', vt: ['courage', 'truthfulness'], w: ['cowardice', 'people-pleasing'] },
  { id: 'crucifixion', era: 'jesus', t: 'The crucifixion', p: 'Luke 23:26–49', v: 'Luke.23.34',
    x: 'Jesus is crucified between two criminals; he prays for his executioners, promises paradise to the penitent thief, entrusts his mother to the beloved disciple, cries the opening of Psalm 22, and dies. A centurion confesses him.',
    m: 'Christians read it as the centre of history: love suffering for others, forgiveness of enemies, and solidarity with the abandoned.', vt: ['forgiveness', 'love', 'sacrifice'] },
  { id: 'resurrection', era: 'jesus', t: 'The resurrection', p: 'Matthew 28; Luke 24; John 20', v: 'Luke.24.6',
    x: 'Women find the tomb empty and are told, “He is not here, but is risen”; Jesus appears to Mary Magdalene, to the disciples, to doubting Thomas, and to two travellers on the road to Emmaus.',
    m: 'For Christians, death is defeated and hope is grounded; doubt is met, not mocked (Thomas).', vt: ['hope', 'joy', 'faith'] },
  { id: 'emmaus', era: 'jesus', t: 'The road to Emmaus', p: 'Luke 24:13–35', v: 'Luke.24.32',
    x: 'Two disheartened disciples walk with a stranger who explains the Scriptures; they recognise Jesus when he breaks bread, and he vanishes.',
    m: 'Christ is recognised in Scripture and the shared meal; burning hearts follow honest questions.', vt: ['hospitality', 'hope', 'understanding'] },

  /* ── Parables ── */
  { id: 'sower', era: 'parables', t: 'The sower', p: 'Mark 4:1–20', v: 'Mark.4.20',
    x: 'Seed falls on the path, rocky ground, thorns and good soil; only the good soil bears fruit thirty, sixty and a hundredfold.',
    m: 'How we hear matters: shallowness, worry and wealth choke the word.', vt: ['attentiveness', 'perseverance'], w: ['distraction', 'shallowness'] },
  { id: 'goodsamaritan', era: 'parables', t: 'The Good Samaritan', p: 'Luke 10:25–37', v: 'Luke.10.36-37',
    x: 'A man is beaten and left on the road; a priest and a Levite pass by, and a despised Samaritan stops, binds his wounds and pays for his care. “Go, and do thou likewise.”',
    m: 'The neighbour is anyone in need; love crosses ethnic and religious hostility and costs something.', vt: ['compassion', 'mercy', 'generosity'], w: ['indifference', 'prejudice'] },
  { id: 'prodigal', era: 'parables', t: 'The prodigal son', p: 'Luke 15:11–32', v: 'Luke.15.20',
    x: 'A younger son wastes his inheritance and returns in disgrace; his father runs to embrace him and throws a feast. The elder brother, who stayed, refuses to join.',
    m: 'God’s mercy runs to meet the repentant; resentment can keep the dutiful outside the celebration.', vt: ['repentance', 'forgiveness', 'mercy'], w: ['resentment', 'self-righteousness'] },
  { id: 'lostsheep', era: 'parables', t: 'The lost sheep and the lost coin', p: 'Luke 15:1–10', v: 'Luke.15.7',
    x: 'A shepherd leaves ninety-nine sheep to find one; a woman sweeps the house for one coin. Each calls friends to rejoice.',
    m: 'Every person matters to God; heaven rejoices over one who repents.', vt: ['care', 'joy'] },
  { id: 'talents', era: 'parables', t: 'The talents', p: 'Matthew 25:14–30', v: 'Matt.25.21',
    x: 'A master entrusts his servants with money; two trade and double it, one buries his out of fear and is rebuked.',
    m: 'Gifts are given to be used; fear is no excuse for doing nothing.', vt: ['stewardship', 'diligence', 'courage'], w: ['sloth', 'fear'] },
  { id: 'sheepgoats', era: 'parables', t: 'The sheep and the goats', p: 'Matthew 25:31–46', v: 'Matt.25.40',
    x: 'At the judgement the king separates people by how they treated the hungry, stranger, sick and prisoner: “ye have done it unto me.”',
    m: 'Christ is met in the needy; mercy is the measure.', vt: ['mercy', 'compassion', 'justice'], w: ['indifference'] },
  { id: 'unforgiving', era: 'parables', t: 'The unforgiving servant', p: 'Matthew 18:21–35', v: 'Matt.18.33',
    x: 'A servant forgiven an unpayable debt throttles a fellow servant over a small one, and is handed over.',
    m: 'Those forgiven much must forgive; unforgiveness imprisons.', vt: ['forgiveness', 'mercy'], w: ['unforgiveness', 'hypocrisy'] },
  { id: 'pharisee', era: 'parables', t: 'The Pharisee and the tax collector', p: 'Luke 18:9–14', v: 'Luke.18.13',
    x: 'A Pharisee thanks God he is not like others; a tax collector beats his breast: “God be merciful to me a sinner.” The second goes home justified.',
    m: 'Humility, not religious achievement, opens the door to God.', vt: ['humility', 'repentance'], w: ['pride', 'contempt'] },
  { id: 'richfool', era: 'parables', t: 'The rich fool', p: 'Luke 12:13–21', v: 'Luke.12.20',
    x: 'A farmer builds bigger barns and tells his soul to take its ease; that night his life is required of him.',
    m: 'Life does not consist in possessions; be rich toward God.', vt: ['generosity', 'wisdom'], w: ['greed', 'complacency'] },
  { id: 'lazarusrich', era: 'parables', t: 'The rich man and Lazarus', p: 'Luke 16:19–31', v: 'Luke.16.25',
    x: 'A rich man ignores the beggar Lazarus at his gate; after death their fortunes are reversed, and a great gulf is fixed between them.',
    m: 'Indifference to the poor at one’s gate is a grave wrong; the Scriptures already warn enough.', vt: ['compassion', 'justice'], w: ['indifference', 'luxury'] },
  { id: 'virgins', era: 'parables', t: 'The ten virgins', p: 'Matthew 25:1–13', v: 'Matt.25.13',
    x: 'Ten bridesmaids wait for the bridegroom; five bring extra oil, five do not and are shut out when he comes at midnight.',
    m: 'Readiness cannot be borrowed at the last minute.', vt: ['preparedness', 'vigilance'], w: ['negligence'] },
  { id: 'mustard', era: 'parables', t: 'The mustard seed and the leaven', p: 'Matthew 13:31–33', v: 'Matt.13.31',
    x: 'The kingdom is like a tiny seed that becomes a tree and like yeast worked through dough.',
    m: 'God’s work begins small and hidden and grows beyond expectation.', vt: ['hope', 'patience'] },
  { id: 'pearl', era: 'parables', t: 'The hidden treasure and the pearl', p: 'Matthew 13:44–46', v: 'Matt.13.44',
    x: 'A man sells everything to buy a field with treasure; a merchant sells all for one pearl.',
    m: 'The kingdom is worth everything, and giving all is joy, not loss.', vt: ['devotion', 'joy', 'wisdom'] },
  { id: 'vineyard', era: 'parables', t: 'The labourers in the vineyard', p: 'Matthew 20:1–16', v: 'Matt.20.15',
    x: 'Workers hired at dawn and at the last hour are paid the same; the first grumble, and the owner asks, “is thine eye evil, because I am good?”',
    m: 'Grace is not wages; envy of another’s gift spoils our own.', vt: ['gratitude', 'generosity'], w: ['envy', 'entitlement'] },
  { id: 'friend', era: 'parables', t: 'The friend at midnight and the persistent widow', p: 'Luke 11:5–13; 18:1–8', v: 'Luke.18.1',
    x: 'A man gets bread from a reluctant friend by persistence; a widow wears down an unjust judge.',
    m: 'Pray and do not lose heart; if even the unjust respond to persistence, how much more God.', vt: ['perseverance', 'prayer', 'hope'] },
  { id: 'twobuilders', era: 'parables', t: 'The wise and foolish builders', p: 'Matthew 7:24–27', v: 'Matt.7.24',
    x: 'One builds on rock, one on sand; the storm comes to both, and only the house on rock stands.',
    m: 'Hearing must become doing; character is built before the storm.', vt: ['wisdom', 'obedience', 'foresight'] },
  { id: 'banquet', era: 'parables', t: 'The great banquet', p: 'Luke 14:15–24', v: 'Luke.14.21',
    x: 'Invited guests make excuses; the host fills his table with the poor, the crippled, the blind and the lame from the streets.',
    m: 'God’s invitation goes to the overlooked when the comfortable decline it.', vt: ['hospitality', 'humility'], w: ['excuses', 'complacency'] },

  /* ── The early church ── */
  { id: 'ascension', era: 'church', t: 'The ascension and Pentecost', p: 'Acts 1–2', v: 'Acts.2.4',
    x: 'Jesus is taken up, telling the disciples they will be his witnesses to the ends of the earth; at Pentecost the Spirit comes with wind and tongues of fire, and the crowd hears in its own languages.',
    m: 'The church is born by gift, speaking every language (Babel reversed); fearful followers become bold.', vt: ['courage', 'unity', 'witness'] },
  { id: 'commonlife', era: 'church', t: 'The first community', p: 'Acts 2:42–47; 4:32–37', v: 'Acts.4.32',
    x: 'Believers devote themselves to teaching, fellowship, breaking bread and prayer, share possessions so that no one is in need, and Barnabas sells a field for the common fund.',
    m: 'Generosity and fellowship as the visible fruit of faith.', vt: ['generosity', 'fellowship', 'unity'] },
  { id: 'ananias', era: 'church', t: 'Ananias and Sapphira', p: 'Acts 5:1–11', v: 'Acts.5.4',
    x: 'A couple sell land and pretend to give all while keeping part; confronted by Peter for lying to the Holy Spirit, each falls dead.',
    m: 'The sin is not keeping money but deceit for reputation; the early community took truthfulness with deadly seriousness.', vt: ['honesty', 'integrity'], w: ['deceit', 'hypocrisy', 'vanity'],
    hard: 'The severity shocks readers; Peter stresses that the money was theirs to keep, so the issue is the lie.' },
  { id: 'stephen', era: 'church', t: 'The stoning of Stephen', p: 'Acts 6–7', v: 'Acts.7.60',
    x: 'Stephen, chosen to serve widows fairly, preaches boldly and is stoned, praying, “Lord, lay not this sin to their charge,” while a young man named Saul approves.',
    m: 'Forgiveness at the point of death; the church’s first martyr echoes Jesus.', vt: ['courage', 'forgiveness', 'service'] },
  { id: 'ethiopian', era: 'church', t: 'Philip and the Ethiopian', p: 'Acts 8:26–40', v: 'Acts.8.35',
    x: 'Philip meets an Ethiopian court official reading Isaiah in his chariot, explains the passage, and baptises him at the roadside.',
    m: 'The gospel crosses barriers of race, nation and status; understanding needs a guide.', vt: ['openness', 'teaching', 'welcome'] },
  { id: 'damascus', era: 'church', t: 'The conversion of Saul', p: 'Acts 9:1–19', v: 'Acts.9.4',
    x: 'Breathing threats, Saul is struck blind on the road to Damascus by a light and a voice: “why persecutest thou me?” Ananias, though afraid, lays hands on him and calls him “Brother Saul.”',
    m: 'No one is beyond transformation; persecuting followers is persecuting Christ; courage to welcome a former enemy.', vt: ['repentance', 'courage', 'forgiveness'] },
  { id: 'cornelius', era: 'church', t: 'Peter and Cornelius', p: 'Acts 10', v: 'Acts.10.34',
    x: 'A vision of unclean animals teaches Peter that God is no respecter of persons; he enters the house of a Roman centurion, and the Spirit falls on the Gentiles.',
    m: 'Prejudice yields to God’s inclusion; the gospel is for every nation.', vt: ['openness', 'humility', 'hospitality'], w: ['prejudice'] },
  { id: 'council', era: 'church', t: 'The Council of Jerusalem', p: 'Acts 15', v: 'Acts.15.11',
    x: 'Apostles and elders debate whether Gentile believers must be circumcised; after testimony and Scripture, they decide not to burden them.',
    m: 'Disagreement resolved by listening, evidence and Scripture; unity without uniformity.', vt: ['wisdom', 'unity', 'listening'] },
  { id: 'prison', era: 'church', t: 'Paul and Silas in prison', p: 'Acts 16:16–40', v: 'Acts.16.25',
    x: 'Beaten and chained in Philippi, Paul and Silas sing hymns at midnight; an earthquake opens the doors, they do not flee, and the jailer and his household are baptised.',
    m: 'Joy in suffering; integrity when escape is easy wins the jailer.', vt: ['joy', 'integrity', 'perseverance'] },
  { id: 'areopagus', era: 'church', t: 'Paul at the Areopagus', p: 'Acts 17:16–34', v: 'Acts.17.28',
    x: 'In Athens Paul starts from an altar “to the unknown god” and quotes Greek poets before speaking of the resurrection; some mock, some believe.',
    m: 'Engaging a culture respectfully on its own terms; truth wherever found points to God.', vt: ['wisdom', 'respect', 'courage'] },
  { id: 'shipwreck', era: 'church', t: 'The shipwreck', p: 'Acts 27–28', v: 'Acts.27.25',
    x: 'On the voyage to Rome, a storm drives the ship for two weeks; the prisoner Paul encourages everyone to eat and all 276 reach Malta safely.',
    m: 'Calm faith in crisis serves everyone; leadership can come from the one in chains.', vt: ['courage', 'hope', 'leadership'] },
  { id: 'onesimus', era: 'church', t: 'Paul, Philemon and Onesimus', p: 'Philemon', v: 'Phlm.1.16',
    x: 'Paul sends the runaway slave Onesimus back to his master Philemon “not now as a servant, but above a servant, a brother beloved,” offering to pay any debt himself.',
    m: 'Faith reorders relationships; reconciliation is mediated at personal cost.', vt: ['reconciliation', 'brotherhood', 'advocacy'],
    hard: 'Paul does not condemn slavery outright here; later Christians (Gregory of Nyssa, the abolitionists) drew the conclusion his “brother beloved” implies.' },
  { id: 'revelation', era: 'church', t: 'The vision of the new Jerusalem', p: 'Revelation 21–22', v: 'Rev.21.4',
    x: 'John sees a new heaven and a new earth; God dwells with his people and “shall wipe away all tears”; the tree of life heals the nations.',
    m: 'The story ends not in escape but in a renewed creation; hope sustains endurance in persecution.', vt: ['hope', 'endurance', 'faithfulness'] }
];
